def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C' if history[0][1] == 'C' else 'D'

    opp = [h[1] for h in history]
    me = [h[0] for h in history]
    opp_last = opp[n - 1]

    # Count defections in recent window
    w = min(10, n)
    rd = 0
    for i in range(n - w, n):
        if opp[i] == 'D':
            rd += 1

    total_opp_c = 0
    for x in opp:
        if x == 'C':
            total_opp_c += 1
    total_opp_d = n - total_opp_c

    # Always defecting opponent
    if total_opp_d == n:
        return 'D'

    # Always cooperating opponent: exploit in endgame only
    if total_opp_c == n:
        if n >= 94:
            return 'D'
        return 'C'

    # Detect TFT-like: opponent mirrors my previous action
    if n >= 8:
        matches = 0
        for i in range(1, n):
            if opp[i] == me[i - 1]:
                matches += 1
        if matches >= n - 2:
            # TFT behavior. Cooperate to keep mutual C, defect only at end.
            if n >= 96:
                return 'D'
            if opp_last == 'D':
                # opponent copying my last D - need to return to C
                # but if I just did D last, cooperate now to reset
                if me[n - 1] == 'D':
                    return 'C'
                return 'D'
            return 'C'

    # Endgame exploitation
    if n >= 95:
        if total_opp_c > total_opp_d:
            return 'D'
        return 'D'

    # Strong recent defection -> retaliate
    if rd >= 4:
        return 'D'

    # If opponent defected last
    if opp_last == 'D':
        # Count consecutive defections
        streak = 0
        i = n - 1
        while i >= 0 and opp[i] == 'D':
            streak += 1
            i -= 1
        if streak >= 2:
            return 'D'
        # Single recent defection: punish once then recover
        if n >= 2 and opp[n - 2] == 'D':
            return 'C'
        # Check overall cooperation to forgive isolated defection
        if total_opp_c >= total_opp_d + 3:
            return 'C'
        return 'D'

    # Opponent cooperated last
    if rd == 0:
        return 'C'

    # Some recent defections but last was C - be cautiously cooperative
    if rd <= 2:
        return 'C'
    return 'D'
